export function UlElement({
  item1 = "{{item1}}",
  item2 = "{{item2}}",
  item3 = "{{item3}}",
  marker = "{{marker}}",
  accent = "{{accent}}",
}) {
  const itemStyle = marker === "check"
    ? { paddingLeft: 26, position: "relative", listStyle: "none" }
    : marker === "disc"
    ? { listStyle: "disc" }
    : { listStyle: "none", paddingLeft: 0 };
  const items = [item1, item2, item3];
  return (
    <ul style={{ width: 260, boxSizing: "border-box", font: "14px/1.7 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: "14px 16px 14px 20px", borderRadius: 12, margin: 0, listStyle: "none" }}>
      {items.map((item) => (
        <li key={item} style={itemStyle}>
          {marker === "check" && <span style={{ position: "absolute", left: 0, color: accent, fontWeight: 800 }}>✓</span>}
          {item}
        </li>
      ))}
    </ul>
  );
}
